import{_ as t,c as a,o,ae as d}from"./chunks/framework.Cd-3tpCq.js";const m=JSON.parse(`{"title":"Set Payment Method","description":"","frontmatter":{"outline":false,"examples":[{"id":"set-payment-method","title":"Set Payment Method","description":"Select a payment method for the order.","request":"POST /api/shop/checkout-payment-methods\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...\\n\\n{\\n  \\"paymentMethod\\": \\"cashondelivery\\"\\n}\\n","response":"HTTP/1.1 201 Created\\n\\n{\\n  \\"success\\": true,\\n  \\"message\\": \\"Payment method saved successfully\\",\\n  \\"cartToken\\": \\"62f2b3f5-a455-4c78-93ba-eabca63d32ec\\",\\n  \\"paymentMethod\\": \\"cashondelivery\\",\\n  \\"paymentRedirectUrl\\": null,\\n  \\"paymentGatewayUrl\\": null,\\n  \\"paymentData\\": null\\n}\\n","commonErrors":[{"error":"500 Internal Server Error — Payment method is required","cause":"paymentMethod was missing, or the body nested it under a payment object","solution":"Send paymentMethod as a top-level string"},{"error":"500 Internal Server Error — Invalid or unavailable payment method","cause":"The code is not one the store currently offers","solution":"Use a method value from Get Payment Methods"},{"error":"401 Unauthorized — Authentication token is required","cause":"No cart or customer token was sent as the Bearer token","solution":"Send the cartToken from Create Cart, or a logged-in customer's token"}]}]},"headers":[],"relativePath":"api/rest-api/shop/checkout/set-payment-method.md","filePath":"api/rest-api/shop/checkout/set-payment-method.md"}`),s={name:"api/rest-api/shop/checkout/set-payment-method.md"};function r(n,e,i,h,c,l){return o(),a("div",null,e[0]||(e[0]=[d(`<h1 id="set-payment-method" tabindex="-1">Set Payment Method <a class="header-anchor" href="#set-payment-method" aria-label="Permalink to &quot;Set Payment Method&quot;">​</a></h1><p>Select a payment method for the order checkout.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/shop/checkout-payment-methods</span></span></code></pre></div><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>The cart&#39;s own token as a Bearer token, or a logged-in customer&#39;s token.</td></tr></tbody></table><h2 id="request-body" tabindex="-1">Request Body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request Body&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;paymentMethod&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cashondelivery&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>paymentMethod</code></td><td>string</td><td>Yes</td><td>The <code>method</code> value of the chosen option from <a href="/api/rest-api/shop/checkout/get-payment-methods.html">Get Payment Methods</a>.</td></tr></tbody></table><p>The field is a <strong>top-level string</strong>. A body that nests it as <code>{&quot;payment&quot;: {&quot;method&quot;: &quot;…&quot;}}</code> is read as missing and fails with <code>Payment method is required</code>.</p><p>Do not hardcode the method list — which codes exist depends on the payment extensions the store has installed and enabled. A store typically offers <code>cashondelivery</code> and <code>moneytransfer</code> out of the box, with gateway methods such as <code>stripe</code>, <code>razorpay</code>, or <code>paypal_standard</code> added on top.</p><h2 id="response-fields-201-created" tabindex="-1">Response Fields (201 Created) <a class="header-anchor" href="#response-fields-201-created" aria-label="Permalink to &quot;Response Fields (201 Created)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>paymentMethod</code></td><td>string</td><td>The method now saved on the cart.</td></tr><tr><td><code>cartToken</code></td><td>string</td><td>The cart&#39;s token, unchanged.</td></tr><tr><td><code>success</code></td><td>boolean</td><td><code>true</code> when the method was saved.</td></tr><tr><td><code>message</code></td><td>string</td><td><code>Payment method saved successfully</code>.</td></tr><tr><td><code>paymentRedirectUrl</code></td><td>string</td><td>Where to send the shopper for an off-site gateway, <code>null</code> for methods that complete in place.</td></tr><tr><td><code>paymentGatewayUrl</code></td><td>string</td><td>Gateway endpoint when the method posts to one, <code>null</code> otherwise.</td></tr><tr><td><code>paymentData</code></td><td>object</td><td>Extra data a gateway needs on the client, <code>null</code> when there is none.</td></tr></tbody></table><p>The response is a confirmation object, not the cart. Fetch <a href="/api/rest-api/shop/cart/get-cart.html">Get Cart</a> if the summary needs refreshing.</p><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rule</th><th>Result</th></tr></thead><tbody><tr><td><code>paymentMethod</code> present at the top level</td><td>Missing or nested → <code>500 Payment method is required</code>.</td></tr><tr><td>The method is currently offered</td><td>Otherwise <code>500 Invalid or unavailable payment method</code>.</td></tr><tr><td>A Bearer token identifies the cart</td><td>Otherwise <code>401 Authentication token is required</code>.</td></tr></tbody></table><p>Unlike the shipping list, the payment list is not address-dependent — it returns the store&#39;s methods whether or not an address has been saved.</p><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Payment step of checkout</strong> — post the selected <code>method</code>, then call <a href="/api/rest-api/shop/checkout/place-order.html">Place Order</a>.</li><li><strong>Redirect to a gateway</strong> — when <code>paymentRedirectUrl</code> comes back non-null, send the shopper there rather than placing the order directly.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Render the options from the API, not a hardcoded list</strong> — the available methods differ per store and per installed extension.</li><li><strong>Check <code>paymentRedirectUrl</code> before showing a &quot;Place order&quot; button</strong> — an off-site method needs the redirect instead.</li><li><strong>Set shipping before payment</strong> — a cart with shippable items and no shipping method cannot be turned into an order.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/checkout/get-payment-methods.html">Get Payment Methods</a> — the payment methods the store offers</li><li><a href="/api/rest-api/shop/checkout/set-billing-address.html">Set Billing Address</a> — save both checkout addresses in one call</li><li><a href="/api/rest-api/shop/checkout/place-order.html">Place Order</a> — turn the prepared cart into an order</li></ul>`,23)]))}const u=t(s,[["render",r]]);export{m as __pageData,u as default};
